/* Evervale rules. Imported records remain intact; adapters declare playable behavior separately. */
(function(scope){
const races=[['human','มนุษย์','ปรับตัวไว • ความชำนาญเพิ่มขึ้น 20%',100],['elf','เอลฟ์','สายใยเวท • เรียนเวทได้ EXP เพิ่ม 2',300],['dwarf','คนแคระ','ช่างฝีมือ • ทำงานได้เงินเพิ่ม 4',180],['halfling','ฮาล์ฟลิ่ง','คล่องตัว • สำรวจใช้พลังงานน้อยลง 3',120],['orc','ออร์ค','กำลังแกร่ง • ฝึกดาบได้ EXP เพิ่ม 2',90],['tiefling','ทีฟลิง','มานาปีศาจ • มานาสูงสุดเพิ่ม 15',150],['dragonborn','ดราก้อนบอร์น','เกล็ดมังกร • ความเสียหายสำรวจลดลง 3',140],['gnome','โนม','ช่างคิด • เรียนใช้เงินน้อยลง 2',220],['fae','ภูติ','พลังธรรมชาติ • พักฟื้นมานาเพิ่ม 10',250]];
const classes=[
['warrior','นักรบ','Fighter','ฝึกฝนอาวุธ','Power Strike','Quick Slash','Sword Mastery','STR'],
['rogue','โจร','Rogue','เงานักเดินทาง','Quick Strike','Backstab','Stealth','DEX'],
['mage','นักเวท','Wizard','สายธารมานา','Arcane Bolt','Fire Burst','Arcana','INT'],
['priest','นักบวช','Cleric','จิตเมตตา','Heal','Holy Strike','Religion','WIS'],
['ranger','พราน','Ranger','ผู้รู้ทางป่า','Precise Shot',"Hunter's Mark",'Survival','DEX'],
['buffer','Buffer','Enchanter','จังหวะแห่งพลัง','Empower','Weaken','Arcana','CHA'],
['alchemist','นักปรุงยา','Alchemist','นักสกัดสาร','ยาฟื้นกำลัง','สารเร่งสมาธิ','Medicine','INT'],
['knight','อัศวิน','Knight','กายเหล็ก','Shield Bash','Guard Ally','Athletics','CON']];
const durations={work:240,train:120,study:120,explore:360,rest:480};
const clone=x=>JSON.parse(JSON.stringify(x));
function fresh(){return {v:3,character:null,minute:480,days:0,ageStart:18,lifespan:90,gold:120,hp:100,energy:100,mp:50,maxMp:50,sword:0,magic:0,trips:0,earned:0,plan:'work',reserve:50,threshold:30,safe:true,dead:false,logs:[],ach:[],event:null,turn:0,lastEyeTurn:null,known:{},learned:[],proficiency:{},buff:null};}
const activitySkills=[{id:'evervale-skill-restorative',name:'ยาฟื้นกำลัง',kind:'skill',category:'Alchemist',activePassive:'Active',description:'วิชาต้นแบบ: เตรียมผลเสริมกิจกรรมถัดไปตามตัวเลขบนหน้าตัวละคร',resourceCost:'5 MP',levelRequirement:1,requiredProficiency:[]},{id:'evervale-skill-focus',name:'สารเร่งสมาธิ',kind:'skill',category:'Alchemist',activePassive:'Active',description:'วิชาต้นแบบ: เตรียมผลเสริมกิจกรรมถัดไปตามตัวเลขบนหน้าตัวละคร',resourceCost:'5 MP',levelRequirement:1,requiredProficiency:[]}];
function records(db){db={...db,skill:[...(db.skill||[]),...activitySkills]};return ['npc','monster','weapon','armor','accessory','helmet','boots','spell','skill','proficiency','item','recipe','dropItem'].flatMap(kind=>(db[kind]||[]).map(x=>({...x,...(db.overrides?.[kind+':'+x.id]||{}),id:x.id,name:x.name,kind,key:kind+':'+x.id})));}
function discover(s,key,depth=0){s.known[key]=Math.max(s.known[key]??-1,depth);}
function has(s,name,db){return s.learned.some(key=>records(db).find(x=>x.key===key)?.name===name);}
function createCharacter(s,name,raceId,classId,db){const race=races.find(x=>x[0]===raceId),job=classes.find(x=>x[0]===classId);if(!race||!job||!name.trim()||name.length>30)throw Error('ตรวจชื่อ เผ่า และคลาสอีกครั้ง');s.character={name:name.trim(),race:raceId,job:classId,level:1,xp:0,stats:{STR:10,DEX:10,CON:10,INT:10,WIS:10,CHA:10}};s.character.stats[job[7]]=14;s.character.stats.CON+=2;s.lifespan=raceId==='human'?80+Math.floor(Math.random()*21):race[3];s.maxMp=raceId==='tiefling'?65:50;s.mp=s.maxMp;
for(const n of [job[4],job[5]]){const row=records(db).find(x=>x.kind==='skill'&&x.name===n);if(row){s.learned.push(row.key);discover(s,row.key,2);}}const prof=records(db).find(x=>x.kind==='proficiency'&&x.name===job[6]);if(prof)discover(s,prof.key,2);s.proficiency[job[6]]=0;return s;}

function validateCharacterImages(input){if(input===undefined||input===null)return {icon:'',portrait:'',combat:''};if(typeof input!=='object'||Array.isArray(input))throw Error('ข้อมูลรูปตัวละครไม่ถูกต้อง');const limits={icon:80000,portrait:240000,combat:480000},out={};for(const key of Object.keys(limits)){const value=input[key]??'';if(typeof value!=='string'||value.length>limits[key])throw Error('รูป '+key+' มีขนาดเกินกำหนด');if(value){if(/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(value)){}else{let url;try{url=new URL(value);}catch{throw Error('รูป '+key+' ต้องเป็นไฟล์ภาพหรือลิงก์ http/https');}if(!['https:','http:'].includes(url.protocol)||value.length>4096)throw Error('ลิงก์รูป '+key+' ไม่ถูกต้อง');}}out[key]=value;}return out;}
function validate(data,db){if(!data||![2,3].includes(data.v))throw Error('รูปแบบเซฟไม่รองรับ');for(const k of ['days','minute','gold','hp','energy','sword','magic','trips','earned','ageStart','lifespan','reserve','threshold'])if(!Number.isFinite(data[k])||data[k]<0||data[k]>1e9)throw Error('ข้อมูลเซฟไม่ถูกต้อง');if(!Number.isInteger(data.days)||!Number.isInteger(data.minute)||data.minute>=1440||!durations[data.plan]||!Array.isArray(data.logs)||data.logs.length>40||data.logs.some(x=>!x||typeof x.text!=='string'||!Number.isInteger(x.day))||!Array.isArray(data.ach)||data.ach.some(x=>typeof x!=='string'))throw Error('ข้อมูลบันทึกไม่ถูกต้อง');
const next={...fresh(),...clone(data),v:3,event:null};if(data.v===3){if(typeof data.known!=='object'||!data.known||Array.isArray(data.known)||Object.values(data.known).some(x=>!Number.isInteger(x)||x<0||x>2)||!Array.isArray(data.learned)||data.learned.some(x=>typeof x!=='string')||typeof data.proficiency!=='object'||!data.proficiency||Array.isArray(data.proficiency)||Object.values(data.proficiency).some(x=>!Number.isFinite(x)||x<0)||!Number.isInteger(data.turn)||data.turn<0||!(data.lastEyeTurn===null||Number.isInteger(data.lastEyeTurn)&&data.lastEyeTurn>=0)||!Number.isFinite(data.mp)||!Number.isFinite(data.maxMp)||data.mp<0||data.maxMp<1||data.mp>data.maxMp)throw Error('ข้อมูลความก้าวหน้าไม่ถูกต้อง');if(data.character){const c=data.character;if(typeof c.name!=='string'||c.name.length>30||!races.some(x=>x[0]===c.race)||!classes.some(x=>x[0]===c.job)||!Number.isInteger(c.level)||c.level<1||!Number.isFinite(c.xp)||c.xp<0||!c.stats||['STR','DEX','CON','INT','WIS','CHA'].some(k=>!Number.isFinite(c.stats[k])||c.stats[k]<0))throw Error('ข้อมูลตัวละครไม่ถูกต้อง');}if(data.event&&data.event.type==='eye')next.event={type:'eye'};}
if(next.character&&next.character.images!==undefined)next.character.images=validateCharacterImages(next.character.images);next.pending=null;next.paused=false;return next;}
function requirements(row){const special=/kishirika|demon-eye|apprais/i.test(row.id+' '+row.name);const stat=(row.damageAbility||(['spell'].includes(row.kind)?'INT':'')).toUpperCase();return {level:Math.max(1,Number(row.levelRequirement)||1),stat:['STR','DEX','CON','INT','WIS','CHA'].includes(stat)?stat:null,minimum:10,profs:Array.isArray(row.requiredProficiency)?row.requiredProficiency:[],special};}
function learnStatus(s,row,db){if(row.enabled===false)return 'รายการนี้ปิดใช้งาน';if(!s.character)return 'ต้องสร้างตัวละครก่อน';if(s.learned.includes(row.key))return 'เรียนแล้ว';if(!(row.key in s.known))return 'ยังไม่ค้นพบ';if((s.known[row.key]||0)<2&&!has(s,'Appraisal Eye',db))return 'ยังไม่ทราบเงื่อนไข • ศึกษาตำราหรือถามอาจารย์';const req=requirements(row);if(req.special)return 'ได้รับจากเหตุการณ์หายาก';if(row.kind==='proficiency')return 'ฝึกผ่านกิจกรรม';if(!playable(row))return 'นำเข้าข้อมูลแล้ว • รอเชื่อมระบบของวิชานี้';const job=classes.find(x=>x[0]===s.character.job);if(['Fighter','Rogue','Wizard','Cleric','Ranger','Enchanter','Alchemist','Knight'].includes(row.category)&&row.category!==job[2])return 'วิชาเฉพาะคลาส '+row.category;if(s.character.level<req.level)return 'เลเวลไม่ถึง '+req.level;if(req.stat&&s.character.stats[req.stat]<req.minimum)return req.stat+' ต้องถึง '+req.minimum;for(const p of req.profs){const n=typeof p==='string'?p:p.name||p.proficiencyName||p.id;const ref=records(db).find(x=>x.id===n||x.name===n);if((s.proficiency[ref?.name||n]||0)<20)return 'ความชำนาญ '+(ref?.name||n)+' ต้องมี 20 EXP';}if(s.gold<20)return 'เหรียญไม่พอ (20)';return '';}
function playable(row){return ['ยาฟื้นกำลัง','สารเร่งสมาธิ','Power Strike','Quick Slash','Quick Strike','Backstab','Arcane Bolt','Fire Burst','Heal','Holy Strike','Precise Shot',"Hunter's Mark",'Empower','Weaken','Shield Bash','Guard Ally','Fire','Ice'].includes(row.name);}
function learn(s,row,db){if(s.dead||s.event)throw Error('ต้องจบเหตุการณ์ก่อนเรียน');const reason=learnStatus(s,row,db);if(reason)throw Error(reason);s.gold-=20;s.learned.push(row.key);clock(s,120);s.turn++;return row.name;}
function clock(s,minutes){const total=s.minute+minutes;s.days+=Math.floor(total/1440);s.minute=total%1440;}
function log(s,text){s.logs.unshift({day:s.days,minute:s.minute,text});s.logs=s.logs.slice(0,40);}
function encounter(s,db,roll=Math.random){if(s.dead||s.event||s.lastEyeTurn!==null&&s.turn-s.lastEyeTurn<30)return false;if(roll()>=.05)return false;s.lastEyeTurn=s.turn;s.event={type:'eye'};return true;}
function grantEye(s,db,roll=Math.random,cost=20){const pool=db.eyes.filter(x=>!has(s,x.skillName,db));if(!pool.length||s.gold<cost||s.event?.type!=='eye')return null;const eye=pool[Math.min(pool.length-1,Math.floor(roll()*pool.length))];const row=records(db).find(x=>x.kind==='skill'&&x.name===eye.skillName);if(!row)return null;s.gold-=cost;s.learned.push(row.key);discover(s,row.key,2);s.event=null;log(s,'คิซิลิก้ามอบ '+eye.label+' • −'+cost+' เหรียญ');return eye;}
function useSkill(s,name,db){if(s.dead||s.event||!s.character)throw Error('ขณะนี้ยังใช้สกิลไม่ได้');const job=classes.find(x=>x[0]===s.character.job);if(!has(s,name,db)&&!(s.character.job==='alchemist'&&[job[4],job[5]].includes(name)))throw Error('ยังไม่ได้เรียน');if(records(db).find(x=>x.name===name)?.enabled===false)throw Error('รายการนี้ปิดใช้งาน');if(s.mp<5)throw Error('มานาไม่พอ (5)');if(s.buff)throw Error('มีสกิลเตรียมใช้แล้ว ทำกิจกรรมเพื่อใช้ผลก่อน');s.mp-=5;s.buff=name;log(s,'เตรียมใช้ '+name+' • มีผลต่อกิจกรรมถัดไป');}
function act(s,a,db,roll=Math.random){if(s.dead||s.event||!s.character)return false;if(s.ageStart+s.days/365>=s.lifespan){s.dead=true;return false;}if(s.hp<45||s.energy<s.threshold)a='rest';else if(s.gold<s.reserve&&a!=='rest')a='work';let cost=a==='train'?8:a==='study'?12:0;if(s.character.job==='alchemist'&&a==='study')cost=Math.max(0,cost-2);if(s.character.race==='gnome')cost=Math.max(0,cost-2);if(s.gold<cost)a='work';else s.gold-=cost;clock(s,durations[a]);s.turn++;if(s.ageStart+s.days/365>=s.lifespan){s.dead=true;log(s,'สิ้นอายุขัย • บันทึกชีวิตบทนี้จบลง');return false;}
const race=s.character.race,job=s.character.job,boost=s.buff?4+(job==='buffer'?2:0):0;let text='';if(a==='work'){const gain=18+(race==='dwarf'?4:0);s.gold+=gain;s.earned+=gain;s.energy-=12;text='ทำงาน +'+gain+' เหรียญ';}if(a==='train'){const gain=8+(race==='orc'?2:0)+(job==='warrior'?2:0)+boost;s.sword+=gain;s.energy-=15;progress(s,'Sword Mastery',gain);text='ฝึกดาบ +'+gain+' EXP';}if(a==='study'){const gain=8+(race==='elf'?2:0)+(job==='mage'?2:0)+boost;s.magic+=gain;s.energy-=13;progress(s,'Arcana',gain);text='เรียนเวท +'+gain+' EXP';}if(a==='rest'){s.energy=Math.min(100,s.energy+35+boost);s.hp=Math.min(100,s.hp+12+(job==='priest'?6:0)+boost);s.mp=Math.min(s.maxMp,s.mp+25+(race==='fae'?10:0));text='พักฟื้น • ฟื้นพลัง สุขภาพ และมานา';}if(a==='explore'){s.trips++;s.energy-=18-(race==='halfling'?3:0)-(job==='ranger'?3:0);const gain=(s.safe?12:20)+Math.floor(roll()*(s.safe?10:25))+(job==='rogue'?4:0)+boost;s.gold+=gain;progress(s,'Survival',8);if(roll()<(s.safe?.08:.3)){const damage=Math.max(0,(s.safe?8:25)-(race==='dragonborn'?3:0)-(job==='knight'?3:0)-boost);s.hp=Math.max(0,s.hp-damage);text='สำรวจ +'+gain+' เหรียญ • บาดเจ็บ '+damage;}else text='สำรวจ +'+gain+' เหรียญ';}if(s.buff){text+=' • ใช้ผล '+s.buff;s.buff=null;}s.energy=Math.max(0,s.energy);s.character.xp+=10;while(s.character.xp>=s.character.level*50){s.character.xp-=s.character.level*50;s.character.level++;const j=classes.find(x=>x[0]===job);s.character.stats[j[7]]++;log(s,'เลเวลเพิ่มเป็น '+s.character.level);}if(s.hp===0){s.dead=true;log(s,'เสียชีวิตระหว่างสำรวจ');}log(s,text);for(const [id,title,ok] of [['first','เงินก้อนแรก',s.earned>=18],['blade','นักดาบฝึกหัด',s.sword>=80],['mage','ประกายเวท',s.magic>=80],['wild','นักสำรวจ',s.trips>=10],['wealth','สร้างฐานะ',s.gold>=1000]])if(ok&&!s.ach.includes(id)){s.ach.push(id);log(s,'✦ '+title);}
if(['study','train','explore'].includes(a)){const pool=records(db).filter(x=>['skill','spell','proficiency'].includes(x.kind)&&x.enabled!==false&&!requirements(x).special&&(a==='study'?x.kind==='spell':a==='train'?x.kind==='skill'&&playable(x):true)&&!(x.key in s.known));if(pool.length){const row=pool[Math.floor(roll()*pool.length)];discover(s,row.key,a==='explore'?0:2);log(s,'ค้นพบ '+row.name+' จาก'+(a==='explore'?'การเดินทาง':'อาจารย์'));}}encounter(s,db,roll);return true;}
function progress(s,n,amount){s.proficiency[n]=(s.proficiency[n]||0)+amount*(s.character.race==='human'?1.2:1);}
const api={validateCharacterImages,races,classes,durations,fresh,records,discover,has,createCharacter,validate,requirements,learnStatus,learn,playable,clock,log,encounter,grantEye,useSkill,act};if(typeof module!=='undefined')module.exports=api;scope.EvervaleRules=api;
})(typeof window==='undefined'?globalThis:window);
